export function clearFieldError(field){field.setCustomValidity('');field.removeAttribute('aria-invalid');const hint=field.closest('.field')?.querySelector('.field-error');if(hint)hint.remove();const ids=(field.getAttribute('aria-describedby')||'').split(' ').filter(x=>x&&x!==field.id+'-error');if(ids.length)field.setAttribute('aria-describedby',ids.join(' '));else field.removeAttribute('aria-describedby')}
export function showFieldError(field,message){field.setAttribute('aria-invalid','true');const parent=field.closest('.field');if(!parent)return;let hint=parent.querySelector('.field-error');if(!hint){hint=document.createElement('small');hint.className='field-error';hint.id=field.id+'-error';parent.append(hint)}hint.textContent=message;const ids=new Set((field.getAttribute('aria-describedby')||'').split(' ').filter(Boolean));ids.add(hint.id);field.setAttribute('aria-describedby',[...ids].join(' '))}
export function bindFormErrors(form){form.noValidate=true;for(const field of form.querySelectorAll('input,select,textarea')){field.addEventListener('input',()=>clearFieldError(field));field.addEventListener('change',()=>clearFieldError(field))}form.addEventListener('invalid',e=>{const f=e.target;const message=f.validity.valueMissing?'Preencha este campo.':f.validity.rangeUnderflow||f.validity.rangeOverflow?'Escolha um valor dentro do intervalo permitido.':f.validity.typeMismatch||f.validity.badInput?'Confira o valor informado.':f.validationMessage;showFieldError(f,message)},true)}
export function checkForm(form){for(const field of form.querySelectorAll('input[required],textarea[required]'))if(['text','search','textarea'].includes(field.type)&&!field.value.trim())field.setCustomValidity('Preencha este campo.');const valid=form.checkValidity();if(!valid)form.querySelector(':invalid')?.focus();return valid}
